const body = $input.first().json.body;

if (!body || !body.record) {
  return [];
}

const oldStatus = body.old_record ? body.old_record.status : null;
const newStatus = body.record.status;

// Caso 1: un draft (o cualquier otro estado) pasó a pending -> avisar cliente + dueño
if (newStatus === 'pending' && oldStatus !== 'pending') {
  return [{ json: { booking_id: body.record.id, kind: 'nueva_pendiente' } }];
}

// Caso 2: una pendiente se resolvió (aprobada o cancelada) -> ticket al cliente
if (oldStatus === 'pending' && (newStatus === 'confirmed' || newStatus === 'cancelled')) {
  return [{ json: { booking_id: body.record.id, kind: 'resuelta', new_status: newStatus } }];
}

// Cualquier otro cambio (ej. edición menor) no nos interesa
return [];

let kind = null;
let newStatus = null;

try { kind = $('Filtrar Insert Pending').item.json.kind; } catch (e) {}
if (!kind) {
